{
  "$schema": "https://charm.land/floyd.json",
  "rules": [
    "NO_CHAT: Be concise. No conversational filler like 'Here is the code' or 'I will do that'.",
    "DATABASE: This project uses sqlc. NEVER edit internal/db/*.sql.go manually. Only edit internal/db/sql/*.sql and run 'sqlc generate'.",
    "FRONTEND: UI logic lives in internal/ui/ (Bubble Tea/Go) AND .floyd/src/ (TypeScript). Verify which layer the user targets.",
    "TESTING: Run tests using 'go test ./...' in the root. Do not use ginkgo or other frameworks unless present.",
    "STYLE: Use 'go fmt' standards. No dot imports. Prefer table-driven tests.",
    "ARCHITECTURE: This is a Go CLI tool using Bubble Tea for TUI. MCP servers provide capabilities (web search, code analysis, etc.)."
  ],
  "providers": {
    "z-ai": {
      "id": "z-ai",
      "name": "Z.AI Coding",
      "type": "anthropic",
      "base_url": "https://api.z.ai/api/anthropic",
      "api_key": "$ANTHROPIC_AUTH_TOKEN",
      "system_prompt_prefix": "You are a precise coding assistant. Ensure your output follows the formatting rules strictly.",
      "models": [
        {
          "id": "claude-sonnet-4-20250514",
          "name": "Claude Sonnet 4"
        }
      ]
    },
    "zai": {
      "id": "zai",
      "name": "GLM-5",
      "type": "openai-compat",
      "base_url": "https://api.z.ai/api/coding/paas/v4",
      "api_key": "$ZAI_API_KEY",
      "system_prompt_prefix": "You are a precise coding assistant. MANDATORY: Your very first text output MUST be the 3-line Boot Summary (Active project, Last known status, Current intent) based on the cache. Think before acting. Use multiedit to batch changes. Be concise and follow format rules strictly.",
      "extra_body": {
        "thinking": {
          "type": "disabled"
        }
      },
      "models": [
        {
          "id": "glm-5",
          "name": "GLM-5",
          "context_window": 204800,
          "default_max_tokens": 32768,
          "can_reason": false,
          "options": {
            "temperature": 0.1
          }
        }
      ]
    }
  },
  "mcp": {
    "floyd-terminal": {
      "type": "stdio",
      "command": "node",
      "args": ["mcp-servers/floyd-terminal/dist/index.js"]
    },
    "novel-concepts": {
      "type": "stdio",
      "command": "node",
      "args": ["/Volumes/Storage/MCP/novel-concepts-server/dist/index.js"]
    }
  },
  "lsp": {
    "gopls": {
      "options": {
        "gofumpt": true,
        "codelenses": {
          "gc_details": true,
          "generate": true,
          "run_govulncheck": true,
          "test": true,
          "tidy": true,
          "upgrade_dependency": true
        },
        "hints": {
          "assignVariableTypes": true,
          "compositeLiteralFields": true,
          "compositeLiteralTypes": true,
          "constantValues": true,
          "functionTypeParameters": true,
          "parameterNames": true,
          "rangeVariableTypes": true
        },
        "analyses": {
          "nilness": true,
          "unusedparams": true,
          "unusedvariable": true,
          "unusedwrite": true,
          "useany": true
        },
        "staticcheck": true,
        "directoryFilters": [
          "-.git",
          "-node_modules"
        ],
        "semanticTokens": true
      }
    }
  }
}

